"use client";

import { motion } from "framer-motion";
import Image from "next/image";

const fadeUp = (delay = 0) => ({
  hidden: { opacity: 0, y: 40 },
  show: {
    opacity: 1,
    y: 0,
    transition: { delay, duration: 0.6, ease: "easeOut" },
  },
});

export default function Portfolio() {
  return (
    <section className="bg-white py-20 px-4 overflow-hidden">
      <div className="max-w-[1300px] mx-auto flex flex-col gap-10">

        {/* HEADING */}
        <motion.div
          variants={fadeUp(0.2)}
          initial="hidden"
          whileInView="show"
          viewport={{ once: true }}
          className="flex flex-col md:flex-row md:items-end md:justify-between gap-4 text-center md:text-left"
        >
          <div>
            <span className="text-purple-700 font-semibold text-xl">
              Our Latest Blogs
            </span>

            <p className="mt-2 text-xl md:text-2xg font-medium text-gray-800">
              What about Beautician Courses?
            </p>
          </div>

          <span className="text-orange-500 font-medium cursor-pointer hover:underline">
            Explore More Courses
          </span>
        </motion.div>

        {/* SHOWCASE IMAGES */}
        <div className="flex flex-wrap justify-center md:justify-between gap-8 p-10">
          
          {[ 
            "https://res.cloudinary.com/dtiaycw2o/image/upload/v1756199690/showCase1_x8bgyk.webp",
            "https://res.cloudinary.com/dtiaycw2o/image/upload/v1756199690/showCase2_rswno4.webp",
            "https://res.cloudinary.com/dtiaycw2o/image/upload/v1756199690/showCase3_sg0ylw.webp",
          ].map((src, i) => (
            <motion.div
              key={i}
              variants={fadeUp(0.4 + i * 0.2)}
              initial="hidden"
              whileInView="show"
              viewport={{ once: true }}
              className="rounded-2xl overflow-hidden shadow-lg cursor-pointer hover:scale-105 transition duration-300"
            >
              <Image
                src={src}
                alt={`showcase-${i}`}
                width={400}
                height={300}
                className="w-full max-w-[330px] max-h-[300px] h-auto object-cover"
              />
            </motion.div>
          ))}

        </div>
      </div>
    </section>
  );
}