"use client";
import { comments, sliderSettings } from "@/src/utils/data";
import Slider from "react-slick";
import { motion } from "framer-motion";
import { footerVariants, staggerChildren } from "@/src/utils/motion";

const People = () => {
  const updatedSliderSettings = {
    ...sliderSettings,
    autoplay: true,
    autoplaySpeed: 3000,
    pauseOnHover: true,
    infinite: true,
    adaptiveHeight: false,
    responsive: [
      {
        breakpoint: 1280,
        settings: { slidesToShow: 3, slidesToScroll: 1 },
      },
      {
        breakpoint: 1024,
        settings: { slidesToShow: 2, slidesToScroll: 1 },
      },
      {
        breakpoint: 640,
        settings: {
          slidesToShow: 1,
          slidesToScroll: 1,
          arrows: false,
          dots: true,
        },
      },
    ],
  };

  return (
    <motion.section
      variants={staggerChildren}
      initial="hidden"
      whileInView="show"
      viewport={{ once: false, amount: 0.01 }}
      className="bg-white px-4 pt-10 pb-14 md:px-8 lg:px-16"
    >
      <a className="block" id="people" />

      <motion.div variants={footerVariants} className="mx-auto max-w-6xl">
        {/* Heading */}
        <div className="mb-6 flex flex-col items-center gap-3 text-center">
          <span className="text-[1.6rem] font-bold text-[#671d8a] sm:text-[2rem] lg:text-[2.5rem]">
            People talk about us
          </span>
          <p className="max-w-xl text-sm leading-relaxed text-gray-600 sm:text-base">
            Our clients rave about Lovely Looks Beauty Salon for exceptional
            services, from makeup and facials to manicures, pedicures, and
            haircuts.
          </p>
          <p className="max-w-xl text-sm leading-relaxed text-gray-600 sm:text-base">
            We provide personalized care and outstanding results, leaving you
            feeling beautiful and confident.
          </p>
        </div>

        {/* Slider */}
        <div className="overflow-visible pt-8 pb-8">
          <Slider
            {...updatedSliderSettings}
            className="[&_.slick-list]:overflow-visible
              [&_.slick-list]:pb-4
              [&_.slick-list]:mx-[-8px]
              [&_.slick-track]:flex
              [&_.slick-slide]:h-auto
              [&_.slick-slide>div]:h-full
              [&_.slick-slide>div]:px-3
              [&_.slick-slide>div]:pt-12
              [&_.slick-dots]:mt-4
              [&_.slick-dots_li_button:before]:text-[#671d8a]
              [&_.slick-dots_li_button:before]:text-[10px]
              [&_.slick-slide.slick-active.slick-current+.slick-slide]:lg:scale-105
              [&_.slick-slide.slick-active.slick-current+.slick-slide]:lg:-translate-y-4
              [&_.slick-slide.slick-active.slick-current+.slick-slide]:lg:transition-all
              [&_.slick-slide.slick-active.slick-current+.slick-slide]:lg:duration-700
              [&_.slick-slide.slick-active.slick-current+.slick-slide]:lg:ease-out"
          >
            {comments.map((comment, i) => (
              <div key={i} className="h-full">
                <div
                  className="relative flex h-full min-h-[280px] flex-col overflow-visible rounded-2xl
                    bg-white  pt-10 pb-10 shadow-[0px_0px_4px_rgba(0,0,0,0.12)]
                    transition-shadow duration-300 hover:shadow-[0px_5px_12px_rgba(0,0,0,0.2)]
                    sm:min-h-[320px] sm:px-5 lg:min-h-[300px]"
                >
                  {/* Avatar */}
                  <img
                    src={comment.img}
                    alt={comment.name}
                    className="absolute -top-6 left-1/2 z-10 h-12 w-12 -translate-x-1/2 rounded-full
                      object-cover ring-2 ring-white shadow-[0px_4px_10px_rgba(0,0,0,0.18)]
                      sm:h-13 sm:w-13 lg:h-14 lg:w-14"
                  />

                  {/* Comment */}
                  <p
                    className="text-center text-[0.78rem] leading-[20px] text-gray-500
                      sm:text-[0.82rem] sm:leading-[22px]
                      lg:text-[0.88rem] lg:leading-[26px]"
                  >
                    {comment.comment}
                  </p>

                  {/* Divider */}
                  <div className="my-2 w-full border-t border-gray-100" />

                  {/* Bio */}
                  <div className="mt-auto flex flex-col items-center gap-0.5">
                    <span className="text-[0.8rem] font-semibold text-gray-800 sm:text-sm lg:text-base">
                      {comment.name}
                    </span>
                    <span className="text-[0.62rem] text-gray-400 sm:text-[0.65rem] lg:text-[0.7rem]">
                      {comment.post}
                    </span>

                    {/* Stars */}
                    <div className="mt-1 flex justify-center gap-0.5">
                      {Array.from({ length: 5 }).map((_, index) => (
                        <span
                          key={index}
                          className="text-sm text-yellow-400 sm:text-base lg:text-lg"
                        >
                          &#9733;
                        </span>
                      ))}
                    </div>
                  </div>
                </div>
              </div>
            ))}
          </Slider>
        </div>
      </motion.div>
    </motion.section>
  );
};

export default People;